/**
 * Database schema for Cloudflare D1 (SQLite), source of truth for drizzle-kit.
 *
 * Conventions:
 * - Ids are UUIDv7 strings generated by the app.
 * - Timestamps are Unix milliseconds (`Date` in code); `createdAt`/`updatedAt` are set by the app,
 *   `updatedAt` on every builder update. Raw SQL updates must set it themselves.
 * - Enums are TEXT columns with a CHECK constraint; booleans are 0/1 integers; JSON is TEXT.
 * - `searchText` columns hold a normalised copy (lowercase, no diacritics) for case- and
 *   accent-insensitive search; keep them in sync with `searchKey()` on every write.
 */
import { sql } from 'drizzle-orm';
import {
  check,
  foreignKey,
  index,
  integer,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core';

import { uuidv7 } from '../lib/uuidv7';

export const ROLES = ['USER', 'HOST', 'ADMIN'] as const;
export const PLATFORMS = ['IOS', 'ANDROID', 'WEB'] as const;
/** Only SINGLE_CHOICE has a handler for now; the others are reserved for future question types. */
export const QUESTION_TYPES = [
  'SINGLE_CHOICE',
  'MULTIPLE_CHOICE',
  'POINT_CHOICE',
  'DRAG_DROP',
  'CALCULATION',
] as const;
export const DIFFICULTIES = ['EASY', 'MEDIUM', 'HARD'] as const;
export const EXAM_STATUSES = ['DRAFT', 'PUBLISHED', 'ARCHIVED'] as const;
export const ATTEMPT_STATUSES = [
  'IN_PROGRESS',
  'SUBMITTED',
  'EXPIRED',
] as const;

export type Role = (typeof ROLES)[number];
export type Platform = (typeof PLATFORMS)[number];
export type QuestionType = (typeof QUESTION_TYPES)[number];
export type Difficulty = (typeof DIFFICULTIES)[number];
export type ExamStatus = (typeof EXAM_STATUSES)[number];
export type AttemptStatus = (typeof ATTEMPT_STATUSES)[number];

const oneOf = (column: string, values: readonly string[]) =>
  sql.raw(`"${column}" IN (${values.map((value) => `'${value}'`).join(', ')})`);

const id = () => text().primaryKey().$defaultFn(uuidv7);
const timestamp = () => integer({ mode: 'timestamp_ms' });
const createdAt = () =>
  timestamp()
    .notNull()
    .$defaultFn(() => new Date());
const updatedAt = () =>
  timestamp()
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdate(() => new Date());
const bool = () => integer({ mode: 'boolean' });
const json = () => text({ mode: 'json' }).$type<unknown>();

export const users = sqliteTable(
  'User',
  {
    id: id(),
    /** Always stored lowercased. */
    email: text().notNull(),
    /** PBKDF2 hash, see src/auth/password.ts. Rows created before accounts existed hold '!' and cannot sign in until re-seeded. */
    passwordHash: text().notNull(),
    fullName: text().notNull(),
    role: text({ enum: ROLES }).notNull().default('USER'),
    isActive: bool().notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('User_email_key').on(t.email),
    check('User_role_check', oneOf('role', ROLES)),
  ],
);

/** One row per signed-in device. The refresh token is `${id}.${secret}`; only sha256(secret) is stored. */
export const sessions = sqliteTable(
  'Session',
  {
    id: id(),
    userId: text().notNull(),
    secretHash: text().notNull(),
    /** Previous secret, accepted for a short grace window after rotation (concurrent refreshes on mobile). */
    prevSecretHash: text(),
    rotatedAt: timestamp(),
    deviceId: text(),
    deviceName: text(),
    platform: text({ enum: PLATFORMS }),
    userAgent: text(),
    ip: text(),
    expiresAt: timestamp().notNull(),
    revokedAt: timestamp(),
    lastUsedAt: timestamp()
      .notNull()
      .$defaultFn(() => new Date()),
    createdAt: createdAt(),
  },
  (t) => [
    index('Session_userId_deviceId_idx').on(t.userId, t.deviceId),
    foreignKey({
      name: 'Session_userId_fkey',
      columns: [t.userId],
      foreignColumns: [users.id],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
    check(
      'Session_platform_check',
      sql`${sql.raw('"platform"')} IS NULL OR ${oneOf('platform', PLATFORMS)}`,
    ),
  ],
);

/** Shared across hosts (e.g. "PMP") so the catalog never shows duplicates. */
export const topics = sqliteTable(
  'Topic',
  {
    id: id(),
    name: text().notNull(),
    slug: text().notNull(),
    description: text(),
    createdById: text().notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('Topic_slug_key').on(t.slug),
    foreignKey({
      name: 'Topic_createdById_fkey',
      columns: [t.createdById],
      foreignColumns: [users.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
  ],
);

/** Knowledge area inside a topic (PMP: People / Process / Business Environment). Tagged on questions, not on sections. */
export const domains = sqliteTable(
  'Domain',
  {
    id: id(),
    topicId: text().notNull(),
    name: text().notNull(),
    description: text(),
    order: integer().notNull().default(0),
    createdById: text().notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('Domain_topicId_name_key').on(t.topicId, t.name),
    foreignKey({
      name: 'Domain_topicId_fkey',
      columns: [t.topicId],
      foreignColumns: [topics.id],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
    foreignKey({
      name: 'Domain_createdById_fkey',
      columns: [t.createdById],
      foreignColumns: [users.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
  ],
);

export const questions = sqliteTable(
  'Question',
  {
    id: id(),
    ownerId: text().notNull(),
    topicId: text().notNull(),
    domainId: text(),
    type: text({ enum: QUESTION_TYPES }).notNull().default('SINGLE_CHOICE'),
    difficulty: text({ enum: DIFFICULTIES }).notNull().default('MEDIUM'),
    /** Question stem (plain text / markdown). */
    content: text().notNull(),
    /** searchKey(content), for the `q` filter. */
    searchText: text().notNull(),
    explanation: text(),
    /** Type-specific payload, validated by the type's handler. */
    definition: json().notNull(),
    /** Bumped on every edit; copied into attempts for per-version statistics. */
    version: integer().notNull().default(1),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('Question_ownerId_topicId_idx').on(t.ownerId, t.topicId),
    index('Question_topicId_domainId_difficulty_idx').on(
      t.topicId,
      t.domainId,
      t.difficulty,
    ),
    foreignKey({
      name: 'Question_ownerId_fkey',
      columns: [t.ownerId],
      foreignColumns: [users.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
    foreignKey({
      name: 'Question_topicId_fkey',
      columns: [t.topicId],
      foreignColumns: [topics.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
    foreignKey({
      name: 'Question_domainId_fkey',
      columns: [t.domainId],
      foreignColumns: [domains.id],
    })
      .onDelete('set null')
      .onUpdate('cascade'),
    check('Question_type_check', oneOf('type', QUESTION_TYPES)),
    check('Question_difficulty_check', oneOf('difficulty', DIFFICULTIES)),
  ],
);

export const exams = sqliteTable(
  'Exam',
  {
    id: id(),
    ownerId: text().notNull(),
    topicId: text().notNull(),
    title: text().notNull(),
    /** searchKey(title), for the catalog `q` filter. */
    searchText: text().notNull(),
    description: text(),
    status: text({ enum: EXAM_STATUSES }).notNull().default('DRAFT'),
    /** null = untimed. */
    durationMinutes: integer(),
    /** Pass mark in percent (0-100); null = no pass/fail. */
    passingScore: integer(),
    shuffleQuestions: bool().notNull().default(false),
    shuffleOptions: bool().notNull().default(false),
    publishedAt: timestamp(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('Exam_ownerId_idx').on(t.ownerId),
    index('Exam_status_topicId_idx').on(t.status, t.topicId),
    foreignKey({
      name: 'Exam_ownerId_fkey',
      columns: [t.ownerId],
      foreignColumns: [users.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
    foreignKey({
      name: 'Exam_topicId_fkey',
      columns: [t.topicId],
      foreignColumns: [topics.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
    check('Exam_status_check', oneOf('status', EXAM_STATUSES)),
  ],
);

/** Every exam has at least one section; an exam "without sections" simply has one. */
export const examSections = sqliteTable(
  'ExamSection',
  {
    id: id(),
    examId: text().notNull(),
    title: text().notNull(),
    order: integer().notNull(),
    instructions: text(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('ExamSection_examId_order_idx').on(t.examId, t.order),
    /** Target of ExamQuestion's composite FK: guarantees a question's section belongs to the same exam. */
    uniqueIndex('ExamSection_id_examId_key').on(t.id, t.examId),
    foreignKey({
      name: 'ExamSection_examId_fkey',
      columns: [t.examId],
      foreignColumns: [exams.id],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
  ],
);

export const examQuestions = sqliteTable(
  'ExamQuestion',
  {
    id: id(),
    examId: text().notNull(),
    sectionId: text().notNull(),
    questionId: text().notNull(),
    order: integer().notNull(),
    points: integer().notNull().default(1),
    createdAt: createdAt(),
  },
  (t) => [
    index('ExamQuestion_sectionId_order_idx').on(t.sectionId, t.order),
    index('ExamQuestion_questionId_idx').on(t.questionId),
    uniqueIndex('ExamQuestion_examId_questionId_key').on(
      t.examId,
      t.questionId,
    ),
    foreignKey({
      name: 'ExamQuestion_examId_fkey',
      columns: [t.examId],
      foreignColumns: [exams.id],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
    foreignKey({
      name: 'ExamQuestion_sectionId_examId_fkey',
      columns: [t.sectionId, t.examId],
      foreignColumns: [examSections.id, examSections.examId],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
    foreignKey({
      name: 'ExamQuestion_questionId_fkey',
      columns: [t.questionId],
      foreignColumns: [questions.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
  ],
);

export const attempts = sqliteTable(
  'Attempt',
  {
    id: id(),
    examId: text().notNull(),
    userId: text().notNull(),
    status: text({ enum: ATTEMPT_STATUSES }).notNull().default('IN_PROGRESS'),
    /** Copied from the exam at start so history survives later edits. */
    examTitle: text().notNull(),
    passingScore: integer(),
    startedAt: timestamp().notNull(),
    /** null = untimed. */
    expiresAt: timestamp(),
    submittedAt: timestamp(),
    /** null while in progress, and briefly after closing until grading is written. */
    score: integer(),
    maxScore: integer().notNull(),
    correctCount: integer(),
    totalQuestions: integer().notNull(),
    passed: bool(),
  },
  (t) => [
    index('Attempt_userId_startedAt_idx').on(t.userId, t.startedAt),
    index('Attempt_examId_idx').on(t.examId),
    /** At most one in-progress attempt per user and exam. */
    uniqueIndex('Attempt_one_in_progress_per_user_exam')
      .on(t.userId, t.examId)
      .where(sql`"status" = 'IN_PROGRESS'`),
    foreignKey({
      name: 'Attempt_examId_fkey',
      columns: [t.examId],
      foreignColumns: [exams.id],
    })
      .onDelete('restrict')
      .onUpdate('cascade'),
    foreignKey({
      name: 'Attempt_userId_fkey',
      columns: [t.userId],
      foreignColumns: [users.id],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
    check('Attempt_status_check', oneOf('status', ATTEMPT_STATUSES)),
  ],
);

/** A question as it was when the attempt started (shuffled options, answer key, explanation). */
export const attemptQuestions = sqliteTable(
  'AttemptQuestion',
  {
    id: id(),
    attemptId: text().notNull(),
    questionId: text(),
    questionVersion: integer().notNull(),
    sectionId: text(),
    sectionTitle: text().notNull(),
    sectionOrder: integer().notNull(),
    order: integer().notNull(),
    points: integer().notNull(),
    snapshot: json().notNull(),
    response: json(),
    isCorrect: bool(),
    score: integer(),
    flagged: bool().notNull().default(false),
    answeredAt: timestamp(),
  },
  (t) => [
    uniqueIndex('AttemptQuestion_attemptId_order_key').on(t.attemptId, t.order),
    index('AttemptQuestion_questionId_idx').on(t.questionId),
    foreignKey({
      name: 'AttemptQuestion_attemptId_fkey',
      columns: [t.attemptId],
      foreignColumns: [attempts.id],
    })
      .onDelete('cascade')
      .onUpdate('cascade'),
    foreignKey({
      name: 'AttemptQuestion_questionId_fkey',
      columns: [t.questionId],
      foreignColumns: [questions.id],
    })
      .onDelete('set null')
      .onUpdate('cascade'),
  ],
);
